package com.ppms.admin.service;
import com.ppms.admin.api.workforce.WorkforceDtos.*;import com.ppms.admin.domain.workforce.*;import com.ppms.admin.repositories.workforce.*;import com.ppms.shared.exception.*;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.LocalDate;import java.util.*;
@Service @RequiredArgsConstructor public class TeamService {private final TeamRepository teams;private final TeamMemberRepository members;private final EmployeeRepository employees;
@Transactional public TeamDto create(TeamRequest r){if(r.leaderEmployeeId()!=null&&!employees.existsById(r.leaderEmployeeId()))throw new EntityNotFoundException("Employee",r.leaderEmployeeId());Team t=new Team();t.setSiteId(r.siteId());t.setName(r.name());t.setLeaderEmployeeId(r.leaderEmployeeId());return dto(teams.save(t));}
@Transactional(readOnly=true) public List<TeamDto> list(UUID siteId){return (siteId==null?teams.findAll():teams.findBySiteId(siteId)).stream().map(this::dto).toList();}
@Transactional public TeamDto addMember(UUID id,TeamMemberRequest r){if(!teams.existsById(id))throw new EntityNotFoundException("Team",id);if(!employees.existsById(r.employeeId()))throw new EntityNotFoundException("Employee",r.employeeId());if(members.findFirstByTeamIdAndEmployeeIdAndToDateIsNull(id,r.employeeId()).isPresent())throw new ValidationException("Employee is already an active team member");TeamMember m=new TeamMember();m.setTeamId(id);m.setEmployeeId(r.employeeId());m.setFromDate(r.fromDate());members.save(m);return dto(teams.findById(id).orElseThrow());}
@Transactional public void removeMember(UUID id,UUID employeeId){TeamMember m=members.findFirstByTeamIdAndEmployeeIdAndToDateIsNull(id,employeeId).orElseThrow(()->new ValidationException("Active team membership not found"));m.setToDate(LocalDate.now());}
private TeamDto dto(Team t){return new TeamDto(t.getId(),t.getSiteId(),t.getName(),t.getLeaderEmployeeId(),members.findByTeamId(t.getId()).stream().map(m->new TeamMemberDto(m.getId(),m.getEmployeeId(),m.getFromDate(),m.getToDate())).toList());}}
